from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class HardRelationError(SchemaObject):
    distname = SchemaField(name="distname", not_null=True)
    error_description = SchemaField(name="error_description", not_null=True)
    error_index = SchemaField(name="error_index", not_null=True)
    mo_uuid = SchemaField(name="mo_uuid", not_null=True)
    nidd_id = SchemaField(name="nidd_id", not_null=True)

    def __init__(self, distname, error_description, error_index, mo_uuid, nidd_id):
        self.distname = distname
        self.error_description = error_description
        self.error_index = error_index
        self.mo_uuid = mo_uuid
        self.nidd_id = nidd_id

        super(HardRelationError, self).__init__()


class ParaRelationError(SchemaObject):
    distname = SchemaField(name="distname", not_null=True)
    error_description = SchemaField(name="error_description", not_null=True)
    error_index = SchemaField(name="error_index", not_null=True)
    mo_uuid = SchemaField(name="mo_uuid", not_null=True)
